// 1. 'const' declares an immutable identifier that cannot be reassigned
const applicationName = "CodePulse";
// applicationName = "NewApp"; // TypeError: Assignment to constant variable.

// 2. 'let' declares block-scoped reassignable variables
let currentScore = 10;
currentScore += 5; // Valid reassignment

// 3. Block scoping: variables declared with let/const exist only inside their block {}
if (true) {
  let blockScopedVar = "visible only inside if-block";
  var functionScopedVar = "leaks outside block!";
}

// console.log(blockScopedVar); // ReferenceError: blockScopedVar is not defined
console.log(functionScopedVar); // Outputs successfully due to legacy function-scoping

// 1. Strict (===) vs Loose (==) Equality
console.log(5 == "5");   // true (performs implicit type coercion)
console.log(5 === "5");  // false (strict: compares both value AND type)

// 2. Arithmetic & Modulo
const remainder = 17 % 5; // 2

// 3. Logical Operators (Short-circuiting)
const userRole = null;
const effectiveRole = userRole || "guest"; // fallback to 'guest'

// 4. Ternary Operator
const age = 20;
const accessLevel = (age >= 18) ? "Adult" : "Minor";
console.log(`Access: ${accessLevel}`); // Adult

/**
 * Calculates circumference and area of a circle.
 * JavaScript identifiers are strictly case-sensitive: 'radius' != 'Radius'.
 */
const radius = 5;
const PI_APPROX = 3.14159;

// Formula: 2 * pi * r
const circumference = 2 * PI_APPROX * radius;

// Formula: pi * r^2
const area = PI_APPROX * (radius ** 2);

console.log(`Radius: ${radius}`);
console.log(`Circumference: ${circumference.toFixed(2)}`);
console.log(`Area: ${area.toFixed(2)}`);
